import { BooleanColumn, ChoiceColumn } from '@servicenow/sdk/core'
import { ActionDefinition } from '@servicenow/sdk/automation'

/**
 * Example 3: Action definition with ChoiceColumn with choices
 *
 * This demonstrates ChoiceColumn with both numeric and string choices.
 */

ActionDefinition({
    $id: Now.ID['action-choice-column'],
    name: 'fl-action-choice-column',
    annotation: 'Test action with ChoiceColumn',
    description: 'Demonstrates ChoiceColumn with choices',
    category: 'Testing',
    inputs: {
        // choices from other table
        priority: ChoiceColumn({
            label: 'Priority',
            mandatory: true,
            dynamicValueDefinitions: {
                type: 'choices_from_other_table',
                table: 'incident',
                field: 'state',
            },
            default: 1,
        }),

        // String choices
        status: ChoiceColumn({
            label: 'Status',
            mandatory: true,
            choices: {
                new: 'New',
                in_progress: 'In Progress',
                on_hold: 'On Hold',
                completed: 'Completed',
                cancelled: 'Cancelled',
            },
            default: 'new',
        }),
    },
    outputs: {
        success: BooleanColumn({
            label: 'Success',
            mandatory: true,
        }),

        // Output with ChoiceColumn
        resultStatus: ChoiceColumn({
            label: 'Result Status',
            mandatory: true,
            choices: {
                success: 'Success',
                warning: 'Warning',
                error: 'Error',
            },
            default: 'success',
        }),
    },
})
